def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    from functools import lru_cache, wraps

    def decorating_function(user_function):
        # Cache storage with time-to-live
        cache_dict = {}
        results_cache = lru_cache(maxsize=maxsize, typed=typed)(cache_dict.get)

        def wrapper(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items()))) if typed else args + tuple(kwargs.values())
            value, creation_time = results_cache(key)
            if value is not None and (timer() - creation_time) < ttl:
                return value
            result = user_function(*args, **kwargs)
            cache_dict[key] = (result, timer())
            return result

        def cache_clear():
            cache_dict.clear()
            results_cache.cache_clear()

        def cache_info():
            return results_cache.cache_info()

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info
        return wraps(user_function)(wrapper)

    return decorating_function

