def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from copy import deepcopy

    def apply_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if op == '&':
                if isinstance(right, tuple) and right[0] == '|' and right[1] == left:
                    return left
                if isinstance(right, tuple) and right[0] == '|' and right[2] == left:
                    return left
                if isinstance(right, tuple) and right[0] == '|' and right[1] == ('~', left):
                    return ('&', left, right[2])
                if isinstance(right, tuple) and right[0] == '|' and right[2] == ('~', left):
                    return ('&', left, right[1])
            elif op == '|':
                if isinstance(right, tuple) and right[0] == '&' and right[1] == left:
                    return left
                if isinstance(right, tuple) and right[0] == '&' and right[2] == left:
                    return left
                if isinstance(right, tuple) and right[0] == '&' and right[1] == ('~', left):
                    return ('|', left, right[2])
                if isinstance(right, tuple) and right[0] == '&' and right[2] == ('~', left):
                    return ('|', left, right[1])
        return expr

    new_args = []
    for expr in args:
        new_args.append(apply_absorption(expr))

    return new_args

