    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    normalized_values = {}
    for attr in self._fields:
        value = getattr(self, attr)
        if isinstance(value, float):
            days_part = int(value)
            hours_part = int((value - days_part) * 24)
            if attr == 'days':
                normalized_values[attr] = days_part
                normalized_values['hours'] = self.hours + hours_part
            elif attr == 'hours':
                normalized_values[attr] = hours_part
                normalized_values['days'] = self.days + days_part
        else:
            normalized_values[attr] = value
    return relativedelta(**normalized_values)

