                # Convert float to integer and handle the remainder
                int_value = int(value)
                normalized_self.__dict__[attr] = int_value
                remainder = value - int_value
                if attr == 'days':
                    normalized_self.hours += remainder * 24
                elif attr == 'months':
                    normalized_self.days += remainder * 30  # Approximation
                elif attr == 'years':
                    normalized_self.months += remainder * 12
            elif attr in ('hours', 'minutes', 'seconds', 'microseconds'):
                int_value = int(value)
                normalized_self.__dict__[attr] = int_value
                remainder = value - int_value
                if attr == 'hours':
                    normalized_self.minutes += remainder * 60
                elif attr == 'minutes':
                    normalized_self.seconds += remainder * 60
                elif attr == 'seconds':
                    normalized_self.microseconds += remainder * 1e6
        else:
            normalized_self.__dict__[attr] = value

    # Recursively normalize nested relativedeltas
    for attr in self._nonspecialattrs:
        value = getattr(self, attr)
        if isinstance(value, relativedelta):
