def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    if verbose:
        print("Running", commands, args)
    stderr = subprocess.DEVNULL if hide_stderr else None
    result = subprocess.run(commands + args, cwd=cwd, env=env, stderr=stderr)
    if verbose:
        print("Command finished with return code", result.returncode)
    return result

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]

    for command in commands:
        cmd = [command] + args
        if verbose:
            print("Running:", ' '.join(cmd))

        stderr = subprocess.DEVNULL if hide_stderr else None
        result = subprocess.run(cmd, cwd=cwd, stderr=stderr, env=env)

        if result.returncode != 0:
            raise subprocess.CalledProcessError(result.returncode, result.args)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    full_command = [commands] + args
    if verbose:
        print("Running command:", ' '.join(full_command))
    with subprocess.Popen(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE if hide_stderr else subprocess.STDOUT) as process:
        stdout, stderr = process.communicate()
        if verbose:
            if stdout:
                print("Standard Output:", stdout.decode().strip())
            if stderr:
                print("Standard Error: ", stderr.decode().strip())
        if process.returncode != 0:
            raise subprocess.CalledProcessError(process.returncode, full_command, output=stdout, stderr=stderr)
        return stdout.decode().strip()

