def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from lxml import etree

    try:
        # Try to parse as JSON
        data = json.loads(document)
        return data
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XRD
        try:
            tree = etree.fromstring(document)
            data = {}
            for elem in tree.findall('.//'):
                tag = elem.tag.split('}')[-1]  # Remove namespace
                text = elem.text.strip() if elem.text else ''
                data[tag] = text
            return data
        except etree.XMLSyntaxError:
            raise ValueError("Document is neither valid JSON nor XRD")

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        import json
        return json.loads(document)
    except json.JSONDecodeError:
        from defusedxml.ElementTree import fromstring as parse_xml
        root = parse_xml(document)
        result = {}
        for elem in root.iter():
            if elem.tag.endswith('}subject'):
                result['subject'] = elem.text
            elif elem.tag.endswith('}alias'):
                if 'aliases' not in result:
                    result['aliases'] = []
                result['aliases'].append(elem.text)
            elif elem.tag.endswith('}link'):
                link = {}
                for attr, value in elem.attrib.items():
                    link[attr] = value
                if 'links' not in result:
                    result['links'] = []
                result['links'].append(link)
        return result

