def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    conditionally_required = []
    for option in options_spec:
        required_when = option.get('required_when')
        if required_when and self._condition_matches(required_when, args):
            conditionally_required.append(option['name'])
    return conditionally_required

def _condition_matches(self, condition, args):
    # Assuming condition is a dictionary in the form {'arg_name': expected_value}
    for arg_name, expected_value in condition.items():
        if args.get(arg_name) != expected_value:
            return False
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    conditionally_required_args = []
    for option in options_spec:
        if 'required_when' in option:
            condition = option['required_when']
            if isinstance(condition, dict):
                if all(args.get(key) == value for key, value in condition.items()):
                    conditionally_required_args.append(option['name'])
            elif callable(condition):
                if condition(command_name, args):
                    conditionally_required_args.append(option['name'])
    return conditionally_required_args

